export type Item = { sku: string; price: number; qty: number };

/** calcTotal: sum of price × quantity over the cart. shippingFee: shipping for the cart, in dollars. */
export const calcTotal = (items: Item[]): number => items.reduce((sum, item) => sum + item.price * item.qty, 0);
export const shippingFee = (items: Item[]): number => (items.length ? 5 : 0);
